import type { ESLintConfigId, PrettierConfigId } from '../types/index.js';

/**
 * Default configuration content for `cspell.config.cjs`.
 */
export const CSPELL_CONFIG_TEMPLATE = `const { defineConfig } = require('@cspell/cspell-types');

module.exports = defineConfig({
  version: '0.2',
  import: ['cspell-config-spellbookx'],
  dictionaryDefinitions: [
    {
      name: 'custom-dict',
      path: './.config/cspell/custom-dictionary.txt',
      addWords: true,
    },
  ],
  dictionaries: ['custom-dict'],
});
`;

