/**
 * Lefthook placeholder resolved to the list of staged files at hook runtime.
 */
const STAGED_FILES = '{staged_files}';

/**
 * Prettier config resolving plugin identifiers to absolute paths so that
 * Prettier can load presets from a flat config file.
 */
const PRETTIER_RESOLVED_TEMPLATE = `import { createRequire } from 'node:module';

import baseConfig from 'prettier-config-spellbookx';

const require = createRequire(
  import.meta.resolve('prettier-config-spellbookx')
);

const config = {
  ...baseConfig,
  plugins: baseConfig.plugins?.map((plugin) =>
    typeof plugin === 'string' ? require.resolve(plugin) : plugin
  ),
  overrides: [...(baseConfig.overrides ?? [])],
};

export default config;
`;

/**
 * Builds the `prettier.config.mjs` content for the selected preset.
 *
 * @param configId - The `prettier-config-spellbookx` preset to re-export.
 * @returns File content for `prettier.config.mjs`.
 */
export function prettierConfigTemplate(configId: PrettierConfigId): string {
  if (configId === 'recommended') {
    return PRETTIER_RESOLVED_TEMPLATE;
  }

  return `export { default } from 'prettier-config-spellbookx/${configId}';
`;
}

/**
 * Builds the `eslint.config.mjs` content for the selected preset.
 *
 * @param configId - The `eslint-plugin-spellbookx` preset to enable.
 * @returns File content for `eslint.config.mjs`.
 */
export function eslintConfigTemplate(configId: ESLintConfigId): string {
  return `import { defineConfig } from 'eslint/config';
import spellbookx from 'eslint-plugin-spellbookx';

export default defineConfig([spellbookx.configs['${configId}']]);
`;
}

/**
 * Lefthook Git hooks configuration, run through the selected package manager.
 *
 * @param pm - Package manager used to execute the hook commands.
 * @returns File content for `lefthook.yml`.
 */
export function lefthookTemplate(pm: string): string {
  return `# Lefthook configuration
# Documentation: https://github.com/evilmartians/lefthook

commit-msg:
  commands:
    commitlint:
      run: ${pm} exec commitlint --edit {1}

pre-commit:
  commands:
    lint:
      run: ${pm} exec eslint --no-warn-ignored --fix ${STAGED_FILES} && ${pm} exec prettier --ignore-unknown --write ${STAGED_FILES}
      stage_fixed: true
`;
}

/**
 * Husky `commit-msg` hook content, run through the selected package manager.
 *
 * @param pm - Package manager used to execute the hook command.
 * @returns File content for `.husky/commit-msg`.
 */
export function huskyCommitMsgTemplate(pm: string): string {
  return `${pm} exec commitlint --edit "$1"
`;
}
